import{_ as a,o as e,c as r,ai as o}from"./chunks/framework.ampVZV4B.js";const b=JSON.parse('{"title":"Go · 02 核心能力","description":"","frontmatter":{},"headers":[],"relativePath":"tech-system/backend/go/02-core.md","filePath":"tech-system/backend/go/02-core.md"}'),d={name:"tech-system/backend/go/02-core.md"};function l(n,t,i,h,c,s){return e(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="go-·-02-核心能力" tabindex="-1">Go · 02 核心能力 <a class="header-anchor" href="#go-·-02-核心能力" aria-label="Permalink to “Go · 02 核心能力”">​</a></h1><h2 id="_1-goroutine-channel" tabindex="-1">1. Goroutine + Channel <a class="header-anchor" href="#_1-goroutine-channel" aria-label="Permalink to “1. Goroutine + Channel”">​</a></h2><p>这是 Go 真正与 Java 不同的体感：</p><ul><li>轻量并发：<code>go func(){...}()</code></li><li>Channel 做通信；「用通信分享内存」而不是处处锁</li><li><code>context</code> 做取消与超时——<strong>必须会用</strong></li></ul><table tabindex="0"><thead><tr><th>适合</th><th>小心</th></tr></thead><tbody><tr><td>网络 IO、worker 池、扇出请求</td><td>goroutine 泄漏（没退出条件）</td></tr><tr><td>代理、边车、简单 API</td><td>无界开 goroutine 打爆内存</td></tr></tbody></table><p>和 Java 线程池比：更轻，但 <strong>泄漏与数据竞争</strong> 一样会要命；<code>go test -race</code> 要会跑。</p><hr><h2 id="_2-性能与部署边界" tabindex="-1">2. 性能与部署边界 <a class="header-anchor" href="#_2-性能与部署边界" aria-label="Permalink to “2. 性能与部署边界”">​</a></h2><ul><li>静态编译、单文件部署，容器友好</li><li>内存与延迟在网络服务场景通常很漂亮</li><li><strong>不是</strong>自动让业务变简单：域复杂、生态组件丰富度仍常输给 Java</li></ul><p>适合：网关、高并发小工具、云原生旁路组件。<br> 不适合（对我）：取代 Java 做整套复杂中台。</p><hr><h2 id="_3-适合-不适合" tabindex="-1">3. 适合 / 不适合 <a class="header-anchor" href="#_3-适合-不适合" aria-label="Permalink to “3. 适合 / 不适合”">​</a></h2><table tabindex="0"><thead><tr><th>适合</th><th>不适合（对我而言）</th></tr></thead><tbody><tr><td>边车、网关、高并发小工具</td><td>取代 Java 做整套 CRM/ERP</td></tr><tr><td>对内存/部署体积敏感</td><td>快速 AI 试错（Python 更快）</td></tr><tr><td>读开源、改小服务</td><td>团队不会 Go 却强行全量迁移</td></tr></tbody></table><h3 id="我为什么了解-go" tabindex="-1">我为什么了解 Go <a class="header-anchor" href="#我为什么了解-go" aria-label="Permalink to “我为什么了解 Go”">​</a></h3><ul><li>读开源、改小服务时用得上</li><li>并发与部署思路能反哺 Java 架构讨论</li><li>不与 Java 抢主业务，做 <strong>补位技能</strong></li></ul><p>下一篇：<a href="./03-frameworks.html">03 框架与生态</a></p>',16)])])}const g=a(d,[["render",l]]);export{b as __pageData,g as default};
